  "inlineSchema": "// Schema del sistema de checador\n// Decisiones clave reflejadas aquí (ver conversación de planeación):\n// - No existe campo de huella: la biometría vive solo en el teléfono del empleado.\n//   El servidor solo guarda la llave pública del dispositivo (esquema tipo passkey).\n// - Entradas y Salidas están unificadas en un solo modelo Asistencia con campo `tipo`.\n// - El timestamp de cada Asistencia lo genera el servidor, nunca el cliente.\n// - El QR de asistencia (rotativo, 30s) NO se persiste aquí: se genera y valida\n//   como token firmado (HMAC + expiración embebida) desde el backend. No necesita tabla.\n// - LecturaSensor fue removido del alcance del proyecto.\n\ngenerator client {\n  provider     = \"prisma-client\"\n  output       = \"../src/generated/prisma\"\n  moduleFormat = \"cjs\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum EstadoEmpleado {\n  ACTIVO\n  INACTIVO\n  BAJA\n}\n\nenum EstadoDispositivo {\n  PENDIENTE // vinculado pero esperando primer check-in / confirmación\n  ACTIVO\n  REVOCADO\n}\n\nenum TipoAsistencia {\n  ENTRADA\n  SALIDA\n}\n\nenum Puntualidad {\n  A_TIEMPO\n  RETARDO\n}\n\nenum TipoMedia {\n  IMAGEN\n  VIDEO\n}\n\nenum RolAdmin {\n  SUPERADMIN\n  ADMIN\n}\n\nmodel Empleado {\n  id             String         @id @default(uuid())\n  nombre         String\n  apellidos      String         @default(\"\")\n  numeroEmpleado String         @unique\n  correo         String?        @unique\n  puesto         String?\n  // Horario esperado general (formato \"HH:mm\"). Si en el futuro se necesitan\n  // horarios distintos por día, esto se mueve a un modelo Horario aparte.\n  horarioEntrada String?\n  horarioSalida  String?\n  estado         EstadoEmpleado @default(ACTIVO)\n  // Hash de contraseña para login móvil (MVP). En producción el acceso se hace\n  // únicamente por biometría + dispositivo registrado; este campo puede eliminarse.\n  passwordHash   String?\n\n  dispositivos      Dispositivo[]\n  asistencias       Asistencia[]\n  codigosActivacion CodigoActivacion[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"empleados\")\n}\n\nmodel Dispositivo {\n  id         String   @id @default(uuid())\n  empleadoId String\n  empleado   Empleado @relation(fields: [empleadoId], references: [id])\n\n  // Llave pública generada por el teléfono (Keychain/Keystore), protegida por biometría.\n  // El servidor NUNCA ve ni guarda la huella en sí, solo esta llave pública.\n  publicKey String @unique\n\n  plataforma String // \"ios\" | \"android\"\n  estado     EstadoDispositivo @default(PENDIENTE)\n\n  fechaRegistro DateTime @default(now())\n\n  asistencias Asistencia[]\n\n  @@map(\"dispositivos\")\n}\n\n// Código/QR de un solo uso que el admin muestra en su pantalla para vincular\n// el teléfono de un empleado nuevo (o uno que cambió de dispositivo).\nmodel CodigoActivacion {\n  id         String   @id @default(uuid())\n  empleadoId String\n  empleado   Empleado @relation(fields: [empleadoId], references: [id])\n\n  codigo   String    @unique\n  expiraEn DateTime\n  usado    Boolean   @default(false)\n  usadoEn  DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@map(\"codigos_activacion\")\n}\n\nmodel Asistencia {\n  id String @id @default(uuid())\n\n  empleadoId String\n  empleado   Empleado @relation(fields: [empleadoId], references: [id])\n\n  dispositivoId String\n  dispositivo   Dispositivo @relation(fields: [dispositivoId], references: [id])\n\n  tipo TipoAsistencia\n\n  // Generado por el servidor al recibir el registro, nunca por el celular.\n  timestamp DateTime @default(now())\n\n  // Fecha \"laboral\" (no necesariamente igual a timestamp) para turnos que\n  // cruzan la medianoche, útil para reportes por día de trabajo.\n  fechaLaboral DateTime @db.Date\n\n  puntualidad Puntualidad?\n\n  // Ruta relativa dentro de storage/fotos-asistencia/, NO la imagen en sí.\n  // Nullable para MVP móvil; en producción siempre se adjunta foto.\n  fotoUrl String?\n\n  createdAt DateTime @default(now())\n\n  @@map(\"asistencias\")\n}\n\nmodel Aviso {\n  id          String   @id @default(uuid())\n  texto       String\n  color       String   @default(\"negro\")\n  fechaInicio DateTime\n  fechaFin    DateTime\n  // Cuando es true, el aviso no expira (se ignora fechaFin en el filtro de la TV).\n  indefinido  Boolean  @default(false)\n  activo      Boolean  @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"avisos\")\n}\n\n// Biblioteca de archivos multimedia subidos. Los archivos se guardan una sola\n// vez y pueden reutilizarse en varios elementos de la cola de reproducción.\nmodel Archivo {\n  id             String    @id @default(uuid())\n  nombreOriginal String\n  // Ruta relativa dentro de storage/media/, NO el archivo en sí.\n  archivoUrl     String    @unique\n  tipo           TipoMedia\n  mimeType       String\n  sizeBytes      Int\n\n  media Media[]\n\n  createdAt DateTime @default(now())\n\n  @@map(\"archivos\")\n}\n\n// Elemento de la cola de reproducción de la TV. Referencia un Archivo de la\n// biblioteca; el orden y la activación controlan qué se muestra en la TV.\nmodel Media {\n  id               String  @id @default(uuid())\n  archivoId        String\n  archivo          Archivo @relation(fields: [archivoId], references: [id], onDelete: Cascade)\n  duracionSegundos Int?\n  orden            Int     @default(0)\n  activo           Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"media\")\n}\n\nmodel Admin {\n  id           String   @id @default(uuid())\n  correo       String   @unique\n  passwordHash String\n  nombre       String\n  rol          RolAdmin @default(ADMIN)\n\n  createdAt DateTime @default(now())\n\n  @@map(\"admins\")\n}\n\nmodel Log {\n  id        String @id @default(uuid())\n  categoria String // ej: \"auth\", \"asistencia\", \"dispositivo\", \"sistema\"\n  mensaje   String\n  metadata  Json?\n\n  createdAt DateTime @default(now())\n\n  @@map(\"logs\")\n}\n",
